package store.cadera.cdrjobs.service;
import org.bukkit.Sound;import org.bukkit.entity.Player;import org.bukkit.potion.*;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.data.*;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.util.Colors;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class FisherService {public static final String JOB="FISHER",OCEANS_CALL="fisher_oceans_call";private final CdrJobsPlugin plugin;private final Database db;private final ProfessionStore store;private final Map<UUID,Long> active=new ConcurrentHashMap<>();public FisherService(CdrJobsPlugin p,Database d,ProfessionStore s){plugin=p;db=d;store=s;}public int rank(Player p,FisherSkill s){return store.getSkillRank(p.getUniqueId(),s.key());}
 public boolean tryUpgrade(Player p,FisherSkill s){int r=rank(p,s);if(r>=s.maxRank()){msg(p,"max-skill");return false;}if(db.getProgress(p.getUniqueId(),JobType.FISHER).level()<s.requiredLevel()){msg(p,"skill-requirement");return false;}if(s.prerequisite()!=null&&rank(p,s.prerequisite())<s.prerequisiteRank()){msg(p,"skill-requirement");return false;}if(s==FisherSkill.OCEANS_CALL&&!tideComplete(p)){p.sendMessage(Colors.color(plugin.prefix()+plugin.message("trial-required").replace("%trial%","Trial of the Tide")));return false;}if(s==FisherSkill.KING_OF_TIDES&&(rank(p,FisherSkill.OCEANS_FAVOR)<3||rank(p,FisherSkill.TREASURE_CALLER)<3||!abyssComplete(p))){msg(p,"skill-requirement");return false;}if(db.getFateEssence(p.getUniqueId())<s.essenceCost()){msg(p,"not-enough-essence");return false;}db.addFateEssence(p.getUniqueId(),-s.essenceCost());store.setSkillRank(p.getUniqueId(),s.key(),r+1);p.sendMessage(Colors.color(plugin.prefix()+plugin.message("skill-unlocked").replace("%skill%",s.displayName()).replace("%rank%",String.valueOf(r+1))));return true;}
 public long applyXp(Player p,long base,boolean ocean,boolean treasure){double m=1.0+rank(p,FisherSkill.TIDEWHISPER)*.05+rank(p,FisherSkill.SWIFT_CURRENT)*.05;if(ocean)m+=rank(p,FisherSkill.ABYSSAL_INSTINCT)*.08;if(treasure)m+=rank(p,FisherSkill.TREASURE_CALLER)*.10;if(rank(p,FisherSkill.KING_OF_TIDES)>0)m+=.20;long xp=Math.max(1,Math.round(base*m));int favor=rank(p,FisherSkill.OCEANS_FAVOR);if(favor>0&&Math.random()<favor*.04)xp*=2;Long until=active.get(p.getUniqueId());if(until!=null){if(until>System.currentTimeMillis()){double b=Math.max(0,plugin.getConfig().getDouble("fisher.abilities.oceans-call.xp-bonus-percent",25));xp=Math.max(1,Math.round(xp*(1+b/100)));}else active.remove(p.getUniqueId());}return xp;}
 public void recordCatch(Player p,boolean treasure,boolean ocean){long catches=store.incrementCounter(p.getUniqueId(),JOB,"catches",1);if(treasure)store.incrementCounter(p.getUniqueId(),JOB,"treasures",1);if(ocean)store.incrementCounter(p.getUniqueId(),JOB,"ocean_catches",1);if(!tideComplete(p)&&catches>=tideTarget()){store.setFlag(p.getUniqueId(),JOB,"trial_tide",true);msg(p,"trial-tide-complete");}if(!abyssComplete(p)&&catches>=abyssCatchTarget()&&treasures(p)>=abyssTreasureTarget()&&oceanCatches(p)>=abyssOceanTarget()){store.setFlag(p.getUniqueId(),JOB,"trial_abyss",true);msg(p,"trial-abyss-complete");}}
 public boolean activate(Player p){if(rank(p,FisherSkill.OCEANS_CALL)<=0){msg(p,"fisher-ability-locked");return false;}long now=System.currentTimeMillis(),ready=store.getAbilityReadyAt(p.getUniqueId(),OCEANS_CALL);if(ready>now){p.sendMessage(Colors.color(plugin.prefix()+plugin.message("fisher-ability-cooldown").replace("%seconds%",String.valueOf((ready-now+999)/1000))));return false;}int dur=Math.max(1,plugin.getConfig().getInt("fisher.abilities.oceans-call.duration-seconds",20)),cd=Math.max(dur,plugin.getConfig().getInt("fisher.abilities.oceans-call.cooldown-seconds",300));active.put(p.getUniqueId(),now+dur*1000L);store.setAbilityReadyAt(p.getUniqueId(),OCEANS_CALL,now+cd*1000L);p.addPotionEffect(new PotionEffect(PotionEffectType.LUCK,dur*20,0,true,false,true));p.playSound(p.getLocation(),Sound.BLOCK_CONDUIT_ACTIVATE,1,1);p.sendMessage(Colors.color(plugin.prefix()+plugin.message("oceans-call-activated").replace("%duration%",String.valueOf(dur))));return true;}
 public long catches(Player p){return store.getCounter(p.getUniqueId(),JOB,"catches");}public long treasures(Player p){return store.getCounter(p.getUniqueId(),JOB,"treasures");}public long oceanCatches(Player p){return store.getCounter(p.getUniqueId(),JOB,"ocean_catches");}public boolean tideComplete(Player p){return store.getFlag(p.getUniqueId(),JOB,"trial_tide");}public boolean abyssComplete(Player p){return store.getFlag(p.getUniqueId(),JOB,"trial_abyss");}public int tideTarget(){return Math.max(1,plugin.getConfig().getInt("fisher.trials.trial-of-tide.catches",250));}public int abyssCatchTarget(){return Math.max(1,plugin.getConfig().getInt("fisher.trials.trial-of-abyss.catches",1000));}public int abyssTreasureTarget(){return Math.max(1,plugin.getConfig().getInt("fisher.trials.trial-of-abyss.treasures",50));}public int abyssOceanTarget(){return Math.max(1,plugin.getConfig().getInt("fisher.trials.trial-of-abyss.ocean-catches",100));}private void msg(Player p,String k){p.sendMessage(Colors.color(plugin.prefix()+plugin.message(k)));}
}
